-- L19-l1-kpopdle-data-fixes.rollback.sql (lane kpopdle, run O1): undoes L19-l1-kpopdle-data-fixes.sql (generated by apps/quiz/scripts/gen-kpopdle-launch.mjs, do not edit by hand).
--
-- What:   puts back the exact previous values of the audit, each only where the row still holds the value L19 wrote (a row changed since is left alone):
--         the curation of Taeil (74) and Mark (80), the seven groups.record_label, the position tags, Minji's roster positions, the Go Won link to Loossemble, the seven
--         debut years and their wikidata / musicbrainz source rows (fetched_at 2026-11-02 12:00 UTC like 021d), the five nationality labels, the ASTRO inception_date;
--         deletes the entity_sources rows of source wikipedia stamped 2026-11-09 00:00 UTC for those values; refreshes the snapshot of kpopdle-idol.
--         Deletes the public.agencies rows L19 created (stamped created_at 2026-11-09 00:00 UTC: BigHit Music, Starship Entertainment, KQ Entertainment, ADOR,
--         SM Entertainment, whichever were missing); a row that existed before L19 stays. Removes the Go Won link only when L19 added it.
--         Then dle_reschedule_undo('L19', 'kpopdle-idol') puts the saved bank (365 days) and the pool_hash back, except today and the served dates, and deletes the saved rows.
-- WHEN:   apply by the owner after a backup, never during a build, never between 23:50 and 00:30 UTC, one launch file at a time, the Verify lines run after it. Nothing waits for a date.
--         Taeil and Mark are answers again, on the days they held before L19.
-- Verify: select count(*) from public.groups where site_id = 'kpop' and (name, record_label) in (('BTS', 'BigHit Music'), ('TXT', 'BigHit Music'), ('IVE', 'Starship Entertainment'), ('ATEEZ', 'KQ Entertainment'), ('RIIZE', 'SM Entertainment'), ('NewJeans', 'ADOR'), ('aespa', 'SM Entertainment'));   expect 0
-- Verify: select record_label from public.groups where site_id = 'kpop' and name = 'aespa';   expect Capitol Records
-- Verify: select count(*) from public.idols where id in (33, 42, 58, 89, 170) and nationality = 'China';   expect 0
-- Verify: select count(*) from public.idols where id in (7, 11, 29, 33, 151, 176, 196) and 'Maknae' = any(positions);   expect 0
-- Verify: select array_to_string(positions, ',') from public.idols where id = 34;   expect Leader,Vocalist
-- Verify: select string_agg(debut_year::text, ',' order by wikidata_qid) from public.idols where wikidata_qid in ('Q491048', 'Q492313', 'Q59313184', 'Q59313270', 'Q59313326', 'Q59313479', 'Q59313527');   expect 2014,2014,2017,2017,2017,2017,2017
-- Verify: select count(*) from public.dle_entities where game_id = 'kpopdle-idol' and can_be_target;   expect 212
-- Verify: select count(*) from public.dle_entities where game_id = 'kpopdle-idol' and entity_id in ('74', '80') and can_be_target;   expect 2
-- Verify: select count(*) from public.dle_schedule where game_id = 'kpopdle-idol' and entity_id in ('74', '80');   expect 4
-- Verify: select count(*) from public.dle_schedule s join public.dle_games g on g.id = s.game_id join public.dle_entities e on e.game_id = s.game_id and e.entity_id = s.entity_id where s.game_id = 'kpopdle-idol' and not (e.can_be_target and e.in_pool) and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(1, 364) as k);   expect 0
-- Verify: select count(*) from public.dle_schedule_backup where file = 'L19' and game_id = 'kpopdle-idol';   expect 0
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent.

do $o1l19r$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

-- Redraw of the scheduled answers a file removes (owner rule 2026-11-09: no waiting for a date). dle_reschedule saves the whole bank of the game and its pool_hash
-- (dle_schedule_backup, first snapshot kept), then gives every coming day (tomorrow to today + 364; never today, never a date already served) whose entity is no longer a
-- valid target (can_be_target, in_pool, not excluded) another valid target: the first by md5(game:bank_day:entity) that is scheduled neither in the 30 days after today nor
-- within 30 days of that date (state as it stands, picks already made included); else the first not scheduled in the 30 days after today; else any valid target.
-- dle_reschedule_undo puts the saved bank and pool_hash back (except today and the served dates) and deletes the saved rows. Both are locked away from the browser roles.
create table if not exists public.dle_schedule_backup (
  file text not null,
  game_id text not null references public.dle_games(id) on delete cascade,
  bank_day smallint not null check (bank_day between 1 and 365),
  entity_id text not null,
  pool_hash text,
  saved_at timestamptz not null default now(),
  primary key (file, game_id, bank_day)
);
alter table public.dle_schedule_backup enable row level security;
revoke all on table public.dle_schedule_backup from public, anon, authenticated;

create or replace function public.dle_reschedule(p_file text, p_game text, p_now timestamptz default now()) returns integer
language plpgsql set search_path = public
as $rs$
declare
  g public.dle_games;
  v_today date := public.dle_utc_date(p_now);
  v_tb integer;
  v_d date;
  v_b integer;
  v_cur text;
  v_pick text;
  v_n integer := 0;
begin
  select * into g from public.dle_games where id = p_game;
  if not found then
    raise exception 'dle_unknown_game';
  end if;
  -- A game that is not live yet has no calendar to protect: its activation will draw from the pool as it is.
  if g.epoch is null or not exists (select 1 from public.dle_schedule where game_id = p_game) then
    return 0;
  end if;
  insert into public.dle_schedule_backup (file, game_id, bank_day, entity_id, pool_hash)
  select p_file, s.game_id, s.bank_day, s.entity_id, g.pool_hash from public.dle_schedule s where s.game_id = p_game
  on conflict (file, game_id, bank_day) do nothing;
  v_tb := public.dle_bank_day(g.epoch, v_today);
  for k in 1..364 loop
    v_d := v_today + k;
    v_b := public.dle_bank_day(g.epoch, v_d);
    if v_b = v_tb or exists (select 1 from public.dle_daily_stats d where d.game_id = p_game and d.play_date = v_d) then
      continue;
    end if;
    select s.entity_id into v_cur from public.dle_schedule s where s.game_id = p_game and s.bank_day = v_b;
    if not found then
      continue;
    end if;
    if exists (select 1 from public.dle_entities e where e.game_id = p_game and e.entity_id = v_cur and e.can_be_target and e.in_pool
      and not exists (select 1 from public.dle_curation c where c.game_id = p_game and c.entity_id = e.entity_id and c.excluded)) then
      continue;
    end if;
    v_pick := null;
    for lvl in 1..3 loop
      select e.entity_id into v_pick from public.dle_entities e
      where e.game_id = p_game and e.can_be_target and e.in_pool
        and not exists (select 1 from public.dle_curation c where c.game_id = p_game and c.entity_id = e.entity_id and c.excluded)
        and (lvl = 3 or not exists (select 1 from public.dle_schedule s where s.game_id = p_game and s.entity_id = e.entity_id
          and s.bank_day in (select public.dle_bank_day(g.epoch, v_today + j) from generate_series(1, 30) as j)))
        and (lvl >= 2 or not exists (select 1 from public.dle_schedule s where s.game_id = p_game and s.entity_id = e.entity_id
          and s.bank_day in (select public.dle_bank_day(g.epoch, v_d + j) from generate_series(-30, 30) as j)))
      order by md5(p_game || ':' || v_b || ':' || e.entity_id), e.entity_id limit 1;
      exit when v_pick is not null;
    end loop;
    if v_pick is null then
      raise exception 'dle_reschedule: no valid target for %', p_game;
    end if;
    update public.dle_schedule set entity_id = v_pick, drawn_at = p_now where game_id = p_game and bank_day = v_b;
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$rs$;

create or replace function public.dle_reschedule_undo(p_file text, p_game text, p_now timestamptz default now()) returns integer
language plpgsql set search_path = public
as $rs$
declare
  g public.dle_games;
  v_tb integer;
  v_hash text;
  v_n integer;
begin
  select * into g from public.dle_games where id = p_game;
  if not found then
    raise exception 'dle_unknown_game';
  end if;
  select b.pool_hash into v_hash from public.dle_schedule_backup b where b.file = p_file and b.game_id = p_game limit 1;
  if not found then
    return 0;
  end if;
  v_tb := public.dle_bank_day(g.epoch, public.dle_utc_date(p_now));
  update public.dle_schedule s set entity_id = b.entity_id, drawn_at = p_now
  from public.dle_schedule_backup b
  where b.file = p_file and b.game_id = p_game and s.game_id = p_game and s.bank_day = b.bank_day and s.entity_id <> b.entity_id
    and s.bank_day <> v_tb
    and not exists (select 1 from public.dle_daily_stats d where d.game_id = p_game and d.play_date >= public.dle_utc_date(p_now)
      and public.dle_bank_day(g.epoch, d.play_date) = s.bank_day);
  get diagnostics v_n = row_count;
  update public.dle_games set pool_hash = v_hash where id = p_game;
  delete from public.dle_schedule_backup where file = p_file and game_id = p_game;
  return v_n;
end;
$rs$;

revoke execute on function public.dle_reschedule(text, text, timestamptz), public.dle_reschedule_undo(text, text, timestamptz) from public, anon, authenticated;

  -- 1. Curation: our own row (marker note, default weight) goes; a row that was there before keeps its weight and gets its flag back.
  delete from public.dle_curation
  where game_id = 'kpopdle-idol' and entity_id in ('74', '80') and excluded and weight = 1 and note like 'L19: left NCT%';
  update public.dle_curation set excluded = false, note = null, updated_at = now()
  where game_id = 'kpopdle-idol' and entity_id in ('74', '80') and excluded and note like 'L19: left NCT%';

  -- 2. Agency.
  update public.groups g set record_label = v.wrong
  from (values
    ('BTS', 'Columbia Records', 'BigHit Music'), ('TXT', 'Republic Records', 'BigHit Music'), ('IVE', 'Columbia Records', 'Starship Entertainment'),
    ('ATEEZ', 'RCA Records', 'KQ Entertainment'), ('RIIZE', 'RCA Records', 'SM Entertainment'), ('NewJeans', 'Geffen Records', 'ADOR'),
    ('aespa', 'Capitol Records', 'SM Entertainment')
  ) as v(name, wrong, fixed)
  where g.name = v.name and g.site_id = 'kpop' and g.record_label = v.fixed;

  -- 3. Positions.
  update public.idols i set positions = array_remove(i.positions, p.tag)
  from (values
    (7, null, 'Jungkook', 'Maknae'), (11, null, 'Lisa', 'Maknae'), (29, null, 'Tzuyu', 'Maknae'), (33, null, 'Ningning', 'Maknae'),
    (151, null, 'Anton Lee', 'Maknae'), (176, null, 'Sehun', 'Maknae'), (196, null, 'Taemin', 'Maknae'),
    (null, 'Q97352009', 'So Jung-hwan', 'Maknae'), (null, 'Q30006465', 'Jongseob', 'Maknae'), (null, 'Q117818064', 'Park Gun-wook', 'Maknae'),
    (null, 'Q233371', 'Taeyeon', 'Leader'), (null, 'Q97319986', 'Junkyu', 'Leader')
  ) as p(idol_id, qid, name, tag)
  where i.name = p.name and ((p.idol_id is not null and i.id = p.idol_id) or (p.qid is not null and i.wikidata_qid = p.qid)) and p.tag = any(i.positions);
  update public.idols set positions = array['Leader', 'Vocalist']::text[]
  where id = 34 and name = 'Minji' and positions = array['Vocalist']::text[];

  -- 4. Go Won leaves Loossemble again, only when L19 added that link (its wikipedia source row exists; a link that was there before has none).
  delete from public.idol_other_groups og
  using public.idols i, public.groups g2
  where i.wikidata_qid = 'Q58825794' and i.name = 'Go Won' and g2.slug = 'loossemble' and og.idol_id = i.id and og.group_id = g2.id
    and exists (select 1 from public.entity_sources e where e.entity_type = 'idol' and e.entity_id = i.id::text and e.field = 'group' and e.source = 'wikipedia'
      and e.fetched_at = timestamptz '2026-11-09 00:00:00+00');

  -- 5. Debut years, then the source rows of the old years (the refs 021d wrote).
  update public.idols i set debut_year = y.old_year
  from (values
    ('Q491048', 'Jay B', 2014, 2012), ('Q492313', 'Jinyoung', 2014, 2012), ('Q59313184', 'JiU', 2017, 2014), ('Q59313270', 'SuA', 2017, 2014),
    ('Q59313326', 'Siyeon', 2017, 2014), ('Q59313479', 'Yoohyeon', 2017, 2014), ('Q59313527', 'Dami', 2017, 2014)
  ) as y(qid, name, old_year, new_year)
  where i.wikidata_qid = y.qid and i.name = y.name and i.debut_year = y.new_year;

  insert into public.entity_sources (entity_type, entity_id, field, source, source_ref, fetched_at)
  select 'idol', i.id::text, 'debut_year', s.source, s.source_ref, timestamptz '2026-11-02 12:00:00+00'
  from (values
    ('Q491048', 'wikidata', 'Q23772001'), ('Q491048', 'musicbrainz', '506745bd-d3e9-4844-a274-99974bef21b2'),
    ('Q492313', 'wikidata', 'Q23772001'), ('Q492313', 'musicbrainz', '506745bd-d3e9-4844-a274-99974bef21b2'),
    ('Q59313184', 'musicbrainz', '51dd3424-23f9-4f6b-bc7b-1218c9ebf3de'), ('Q59313270', 'musicbrainz', '51dd3424-23f9-4f6b-bc7b-1218c9ebf3de'),
    ('Q59313326', 'musicbrainz', '51dd3424-23f9-4f6b-bc7b-1218c9ebf3de'), ('Q59313479', 'musicbrainz', '51dd3424-23f9-4f6b-bc7b-1218c9ebf3de'),
    ('Q59313527', 'musicbrainz', '51dd3424-23f9-4f6b-bc7b-1218c9ebf3de')
  ) as s(qid, source, source_ref)
  join public.idols i on i.wikidata_qid = s.qid
  where i.debut_year in (2014, 2017) and exists (
      select 1 from public.entity_sources w where w.entity_type = 'idol' and w.entity_id = i.id::text and w.field = 'debut_year' and w.source = 'wikipedia'
        and w.fetched_at = timestamptz '2026-11-09 00:00:00+00')
  on conflict (entity_type, entity_id, field, source) do nothing;

  -- 6. Nationality labels.
  update public.idols i set nationality = w.wrong
  from (values
    (33, 'Ningning'), (42, 'Jun'), (58, 'Yuqi'), (89, 'Qian Kun'), (170, 'Lay')
  ) as x(id, name)
  cross join (select 'People''s Republic of China'::text as wrong) w
  where i.id = x.id and i.name = x.name and i.nationality = 'China';

  -- 7. ASTRO.
  update public.groups set inception_date = date '2016-01-01'
  where name = 'ASTRO' and site_id = 'kpop' and inception_date = date '2016-02-23';

  -- 8. The wikipedia source rows of L19 (the stamp tells which are ours).
  delete from public.entity_sources e
  where e.source = 'wikipedia' and e.fetched_at = timestamptz '2026-11-09 00:00:00+00' and (
       (e.entity_type = 'group' and e.field in ('record_label', 'inception_date'))
    or (e.entity_type = 'idol' and e.field in ('positions', 'group', 'debut_year')));

  -- 9. The agency rows L19 created (stamped), unless one has a child. A row that existed before has another created_at and stays.
  delete from public.agencies a
  where a.created_at = timestamptz '2026-11-09 00:00:00+00' and a.name in ('BigHit Music', 'Starship Entertainment', 'KQ Entertainment', 'ADOR', 'SM Entertainment')
    and not exists (select 1 from public.agencies c where c.parent_id = a.id);

  -- 10. The snapshot, then the calendar as it was saved (the pool_hash with it), then the snapshot again now that the calendar is back.
  if exists (select 1 from public.dle_entities where game_id = 'kpopdle-idol') then
    perform public.dle_refresh_entities('kpopdle-idol');
  end if;
  perform public.dle_reschedule_undo('L19', 'kpopdle-idol');
  if exists (select 1 from public.dle_entities where game_id = 'kpopdle-idol') then
    perform public.dle_refresh_entities('kpopdle-idol');
  end if;

  notify pgrst, 'reload schema';
end $o1l19r$;
